$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$errors=@();Get-ChildItem $root -Filter *.html|ForEach-Object{$file=$_;$html=Get-Content -Raw $file.FullName;[regex]::Matches($html,'(?:href|src)="([^"#?]+)')|ForEach-Object{$ref=$_.Groups[1].Value;if($ref-match'^(?:https?:|mailto:|tel:|data:)'){return};$target=Join-Path $root $ref.Replace('/','\');if(-not(Test-Path $target)){$errors+="$($file.Name): $ref"}}};if($errors){throw("Missing references:`n"+($errors-join"`n"))};'Internal file references resolved.'
